from decimal import Decimal
from fractions import Fraction


def _decimal(value: object) -> Decimal:
    """Apply legacy NVL(value, 0) numeric coercion without float artifacts."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    if isinstance(value, bool):
        return Decimal(int(value))
    return Decimal(str(value))


def _round_half_up_cents(value: Fraction) -> int:
    """Return an exact value as integer cents, rounding ties away from zero."""
    scaled = value * 100
    if scaled >= 0:
        return (2 * scaled.numerator + scaled.denominator) // (
            2 * scaled.denominator
        )
    scaled = -scaled
    return -(
        (2 * scaled.numerator + scaled.denominator)
        // (2 * scaled.denominator)
    )


def _cents_decimal(cents: int) -> Decimal:
    sign = 1 if cents < 0 else 0
    digits = tuple(int(char) for char in str(abs(cents)))
    return Decimal((sign, digits, -2))


def recompute(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list]:
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    total_cents = 0

    for source_line, new_line in zip(lines, new_lines):
        if source_line.get("DEL_FLG") == "Y":
            continue

        quantity = Fraction(_decimal(source_line.get("QTY")))
        unit_price = Fraction(_decimal(source_line.get("UNIT_PRC")))
        ext_cents = _round_half_up_cents(quantity * unit_price)

        new_line["EXT_AMT"] = float(_cents_decimal(ext_cents))
        total_cents += ext_cents

    discount = Fraction(_decimal(order.get("DISC_PCT")))
    total = Fraction(total_cents, 100)
    discounted = total * (Fraction(100) - discount) / 100
    discounted_cents = _round_half_up_cents(discounted)
    discounted_decimal = _cents_decimal(discounted_cents)

    new_order["TOT_AMT"] = float(discounted_decimal)

    incoming_total = Fraction(_decimal(order.get("TOT_AMT")))
    recomputed_total = Fraction(discounted_decimal)
    audits = []

    if incoming_total != recomputed_total:
        audits.append(("ORD_RETOTAL", order.get("ORD_ID")))

    return new_order, new_lines, audits
